<script lang="ts">
  import type { PokedexCardSnapshot } from '../../bus/snapshots.js';
  import { pokedex } from '../../stores/pokedex.svelte.ts';
  import { captureUiScrollPositions, restoreUiScrollPositions } from '../../lib/uiScrollPreserve.ts';
  import {
    cancelStorageExpansion,
    requestStorageExpansion,
  } from '../../lib/storageGridExpansion.ts';
  import {
    clampStorageWindow,
    DEFAULT_POKEDEX_ROW_HEIGHT,
    getStorageVirtualSpacerHeights,
    measureStableGridMetrics,
    syncStorageWindowFromScroll,
    type GridRowMetrics,
  } from '../../lib/storageVirtualScroll.ts';
  import { getLazyListScrollRoot } from '../../../formatters.ts';
  import { isMobileViewport } from '../../ui/breakpoints.ts';
  import { bindVirtualGridResizeSync } from '../../lib/virtualGridResizeSync.ts';
  import PokedexCard from './PokedexCard.svelte';

  const POKEDEX_BATCH_SIZE = 48;
  const POKEDEX_BATCH_SIZE_MOBILE = 24;
  const POKEDEX_CHUNK_SIZE = 6;
  const POKEDEX_CHUNK_SIZE_MOBILE = 4;
  const POKEDEX_MAX_DOM = 120;
  const POKEDEX_MAX_DOM_MOBILE = 60;
  const POKEDEX_SCROLL_ROOT = '.secondary-content';

  let { batchSize = POKEDEX_BATCH_SIZE }: { batchSize?: number } = $props();

  function effectiveBatchSize(): number {
    return isMobileViewport() ? POKEDEX_BATCH_SIZE_MOBILE : batchSize;
  }

  function effectiveChunkSize(): number {
    return isMobileViewport() ? POKEDEX_CHUNK_SIZE_MOBILE : POKEDEX_CHUNK_SIZE;
  }

  function effectiveMaxDom(): number {
    return isMobileViewport() ? POKEDEX_MAX_DOM_MOBILE : POKEDEX_MAX_DOM;
  }

  function defaultCachedMetrics(): GridRowMetrics {
    return { cols: 4, rowHeight: DEFAULT_POKEDEX_ROW_HEIGHT };
  }

  function scrollBatchBuffer(): number {
    return Math.min(effectiveBatchSize(), cachedMetrics.cols * 3);
  }

  let listEl = $state<HTMLElement | null>(null);
  let visibleCount = $state(isMobileViewport() ? POKEDEX_BATCH_SIZE_MOBILE : POKEDEX_BATCH_SIZE);
  let windowStart = $state(0);
  let expansionTargetEnd = $state(0);
  let sentinelEl = $state<HTMLDivElement | null>(null);
  let lastCardsSig = $state('');
  let sentinelObserveKey = $state(0);
  let cachedMetrics = $state<GridRowMetrics>(defaultCachedMetrics());

  let cards = $derived(pokedex.snapshot.cards);

  let visibleCards = $derived(
    cards.slice(windowStart, Math.min(windowStart + visibleCount, cards.length)),
  );

  let spacerHeights = $derived.by(() => {
    void visibleCards.length;
    void cachedMetrics.rowHeight;
    return getStorageVirtualSpacerHeights(
      listEl,
      windowStart,
      visibleCount,
      cards.length,
      DEFAULT_POKEDEX_ROW_HEIGHT,
      cachedMetrics,
    );
  });

  function pokedexCardsSignature(list: PokedexCardSnapshot[]): string {
    if (list.length === 0) return '';
    return `${list.length}:${list[0]?.cardKey ?? ''}:${list.at(-1)?.cardKey ?? ''}`;
  }

  function refreshCachedMetrics(): void {
    const el = listEl;
    if (!el) return;
    cachedMetrics = measureStableGridMetrics(el, DEFAULT_POKEDEX_ROW_HEIGHT, cachedMetrics);
  }

  function applyClampWindow(): void {
    const batch = effectiveBatchSize();
    const maxDom = effectiveMaxDom();
    const clamped = clampStorageWindow(cards.length, windowStart, visibleCount, batch, maxDom);
    windowStart = clamped.windowStart;
    visibleCount = clamped.visibleCount;
  }

  function syncWindowFromScroll(): void {
    const el = listEl;
    if (!el) return;
    const synced = syncStorageWindowFromScroll(
      el,
      cards.length,
      effectiveMaxDom(),
      scrollBatchBuffer(),
      POKEDEX_SCROLL_ROOT,
      DEFAULT_POKEDEX_ROW_HEIGHT,
      cachedMetrics,
    );
    if (!synced) return;
    windowStart = synced.windowStart;
    visibleCount = synced.visibleCount;
    applyClampWindow();
    expansionTargetEnd = Math.max(expansionTargetEnd, windowStart + visibleCount);
  }

  function bumpSentinelObserver(): void {
    sentinelObserveKey += 1;
  }

  function queueExpansion(): void {
    requestStorageExpansion({
      getCreaturesLength: () => cards.length,
      getWindowStart: () => windowStart,
      getVisibleCount: () => visibleCount,
      setVisibleCount: (v) => {
        visibleCount = v;
        applyClampWindow();
      },
      getExpansionTargetEnd: () => expansionTargetEnd,
      setExpansionTargetEnd: (v) => { expansionTargetEnd = v; },
      onBatchComplete: bumpSentinelObserver,
      batch: effectiveBatchSize(),
      maxDom: effectiveMaxDom(),
      chunk: effectiveChunkSize(),
    });
  }

  $effect(() => {
    void visibleCards.length;
    const el = listEl;
    if (!el) return;
    const metricsRaf = requestAnimationFrame(() => {
      refreshCachedMetrics();
    });
    return () => cancelAnimationFrame(metricsRaf);
  });

  $effect(() => {
    const el = listEl;
    if (!el) return;
    return bindVirtualGridResizeSync(el, () => {
      refreshCachedMetrics();
      syncWindowFromScroll();
    });
  });

  $effect(() => {
    const el = listEl;
    const root = getLazyListScrollRoot(el, POKEDEX_SCROLL_ROOT);
    if (!el || !(root instanceof HTMLElement)) return;

    let scrollRaf: number | null = null;
    const onScroll = () => {
      if (scrollRaf != null) return;
      scrollRaf = requestAnimationFrame(() => {
        scrollRaf = null;
        syncWindowFromScroll();
      });
    };

    root.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      root.removeEventListener('scroll', onScroll);
      if (scrollRaf != null) cancelAnimationFrame(scrollRaf);
    };
  });

  $effect(() => {
    sentinelObserveKey;
    const el = sentinelEl;
    const root = getLazyListScrollRoot(listEl, POKEDEX_SCROLL_ROOT);
    const len = cards.length;
    if (!el || typeof IntersectionObserver === 'undefined') return;
    const obs = new IntersectionObserver(
      (entries) => {
        if (!entries.some((e) => e.isIntersecting)) return;
        if (windowStart + visibleCount >= len) return;
        queueExpansion();
      },
      { root, rootMargin: '200px', threshold: 0 },
    );
    obs.observe(el);
    return () => obs.disconnect();
  });

  $effect(() => {
    const sig = pokedexCardsSignature(cards);
    if (sig !== lastCardsSig) {
      const scrollSaved = captureUiScrollPositions();
      lastCardsSig = sig;
      cancelStorageExpansion();
      cachedMetrics = defaultCachedMetrics();
      windowStart = 0;
      visibleCount = Math.min(effectiveBatchSize(), cards.length);
      expansionTargetEnd = visibleCount;
      applyClampWindow();
      restoreUiScrollPositions(scrollSaved);
    } else {
      applyClampWindow();
    }
  });
</script>

<div bind:this={listEl} class="team-list" id="pokedexList">
  {#if cards.length === 0}
    <div style="text-align: center; color: #666; padding: 20px; grid-column: 1 / -1;">
      {pokedex.snapshot.cardsEmptyMessage}
    </div>
  {:else}
    {#if spacerHeights.topPx > 0}
      <div
        class="storage-grid-spacer storage-grid-spacer--top"
        style="height: {spacerHeights.topPx}px"
        aria-hidden="true"
      ></div>
    {/if}
    {#each visibleCards as card (card.cardKey)}
      <PokedexCard {card} />
    {/each}
    {#if windowStart + visibleCount < cards.length}
      <div class="storage-grid-sentinel" bind:this={sentinelEl} aria-hidden="true"></div>
    {/if}
    {#if spacerHeights.bottomPx > 0}
      <div
        class="storage-grid-spacer storage-grid-spacer--bottom"
        style="height: {spacerHeights.bottomPx}px"
        aria-hidden="true"
      ></div>
    {/if}
  {/if}
</div>
